import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("tree search", () => {
  test("tree search", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.loadSheet(pg_uma, `${sheet}-p`);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_pam = ui.must(await ui.addPerson(pg_uma, {"name": "Pam", "grade": "A"}));
    const p_bea = ui.must(await ui.addPerson(pg_uma, {"name": "Bea", "grade": "B"}));
    const c_pam_0 = ui.must(await ui.addClaim(pg_uma, p_pam, {"amount": "1.00"}));
    expect(await ui.claimAction(pg_uma, c_pam_0, "open")).toBe(true);
    await ui.loadSheet(pg_uma, sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    expect(await ui.addAlias(pg_uma, p_ben, "Pal")).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.setToday(pg_uma, "2026-03-10");
    await ui.setSetting(pg_uma, "parent", `${sheet}`);
    const p_cal = ui.must(await ui.addPerson(pg_uma, {"name": "Cal", "grade": "A"}));
    await ui.loadSheet(pg_uma, sheet);
    expect(await ui.search(pg_uma, "a")).toEqual([`${sheet} Ada 2.00`, `${sheet} Ben n/a`, `${sheet}-c Cal 0.00`, `${sheet}-p Pam 1.00`, `${sheet}-p Bea n/a`]);
    expect(await ui.search(pg_uma, "PA")).toEqual([`${sheet} Ben n/a`, `${sheet}-p Pam 1.00`]);
    expect(await ui.search(pg_uma, "zz")).toEqual([]);
    expect(await ui.search(pg_uma, "")).toEqual([`${sheet} Ada 2.00`, `${sheet} Ben n/a`, `${sheet}-c Cal 0.00`, `${sheet}-p Pam 1.00`, `${sheet}-p Bea n/a`]);
    expect(await ui.retire(pg_uma, p_ada, "2026-03-01")).toBe(true);
    await ui.showRetired(pg_uma, true);
    expect(await ui.hold(pg_uma, p_ben, {"from": "2026-03-01"})).toBe(true);
    expect(await ui.search(pg_uma, "a")).toEqual([`${sheet} Ada 0.00`, `${sheet} Ben n/a`, `${sheet}-c Cal 0.00`, `${sheet}-p Pam 1.00`, `${sheet}-p Bea n/a`]);
    await ui.refresh(pg_uma);
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=parent value=${sheet}-p`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ALIAS_ADDED sheet=${sheet} by=uma name=Ben alias=Pal`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10 number=FY2026-2`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=2.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=10.00 due-total=2.00 overdue-total=0.00`,
      `PERSON_RETIRED sheet=${sheet} by=uma name=Ada from=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_HELD sheet=${sheet} by=uma name=Ben from=2026-03-01`
    ]);
  });
  test("tree search scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
